def await_ownership(
    self, record: "OperationRecord", timeout: float = LOCK_WAIT_SECONDS
):
    """Wait until a pending operation's live owner has released its lease.

    A same-binding retry that finds the operation still ``pending`` must
    not execute while the original owner process might be running (that
    would mint a second set of handles). It blocks up to ``timeout`` for
    the owner's execution lease; on success it returns an open fd that now
    holds the lease (the retry owns the attempt and must rebuild the
    mirror / continue it). If the owner stays alive past the deadline it
    returns None (the caller answers 503 without writing anything).
    """
    deadline = time.monotonic() + timeout
    while True:
        fd = self.acquire_lease(
            record.operation_id, blocking=False
        )
        if fd is not None:
            return fd
        remaining = deadline - time.monotonic()
        if remaining <= 0:
            return None
        time.sleep(min(_POLL_SECONDS, remaining))

